'use strict';
const R=JSON.parse(document.getElementById('research-data').textContent);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>n==null||!Number.isFinite(+n)?'n/a':new Intl.NumberFormat('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}).format(n);
const money=n=>n==null?'n/a':'$'+(Math.abs(n)>=1e9?num(n/1e9,3)+'bn':Math.abs(n)>=1e6?num(n/1e6,3)+'m':num(n,0));
const pct=(n,d=3)=>n==null?'n/a':num(n*100,d)+'%';
const date=t=>t==null?'n/a':new Date(t*1000).toISOString().slice(0,10);
const short=a=>a?.startsWith('0x')?a.slice(0,8)+'…'+a.slice(-4):a;
const a=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;
const explorer=(chain,address)=>({ethereum:'https://etherscan.io/address/',base:'https://basescan.org/address/',arbitrum:'https://arbiscan.io/address/',optimism:'https://optimistic.etherscan.io/address/'}[chain]||'https://etherscan.io/address/')+address;
const article=(id,text='Full dossier →')=>`<a class="btn" href="dossiers/${id}.html">${text}</a>`;

function initTheme(){let theme;try{theme=localStorage.getItem('eth-research-theme')}catch{};if(theme)document.documentElement.dataset.theme=theme;$('#theme').onclick=()=>{let dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);let next=dark?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('eth-research-theme',next)}catch{}};$('#print').onclick=()=>window.print();}
function initChains(){const top=R.chains.slice(0,10),max=top[0].reported_full_pool_tvl_usd;$('#chain-bars').innerHTML=top.map(c=>`<div class="bar-row"><span>${esc(c.chain)}</span><div class="bar-track"><span style="width:${100*c.reported_full_pool_tvl_usd/max}%"></span></div><b>${money(c.reported_full_pool_tvl_usd)}</b></div>`).join('');$('#chain-table tbody').innerHTML=R.chains.map(c=>`<tr><td>${esc(c.chain)}</td><td class="n">${num(c.pools)}</td><td class="n">${money(c.reported_full_pool_tvl_usd)}</td><td class="n">${c.above_5m_pools}</td><td>${c.deep_candidate?'Core focus':'Discovery / dependencies'}</td></tr>`).join('');}
const CAPITAL={underlying:['100 ETH issuer backing; 70 ETH external loan','Backing of the initial receipt issuance. Subsequent claims and loans do not create additional ETH for this issuer. The 70 ETH loan belongs to a different capital root and requires separate reconciliation.'],equity:['100 ETH','Investor equity: 170 ETH gross assets − 70 ETH debt. LSTs, restaking receipts and vault shares represent capital claims; they do not add new deposits.'],deployment:['170 ETH collateral; 70 ETH debt','Gross positions measure platform exposure: 100 ETH of initial collateral plus 70 ETH redeployed. Staking/restaking backing and gross lending positions overlap; their sum is not unique capital.']};
function capital(k){$$('#capital-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.capital===k)));$('#capital-value').textContent=CAPITAL[k][0];$('#capital-explain').textContent=CAPITAL[k][1];}
let allProtocols=false;
function protocols(){const q=$('#protocol-q').value.toLowerCase().trim(),cat=$('#protocol-category').value;let rows=R.protocols.filter(r=>(!cat||r.category_current_hint===cat)&&[r.name,r.protocol,...Object.keys(r.tokens_usd||{})].join(' ').toLowerCase().includes(q));rows.sort($('#protocol-sort').value==='name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>b.eth_family_reported_usd-a.eth_family_reported_usd);$('#protocol-count').textContent=`${rows.length} of ${R.protocols.length} dated protocol observations · overlapping balances`;$('#protocol-table tbody').innerHTML=rows.slice(0,allProtocols?1e4:15).map(r=>`<tr><td>${a(r.source_url,r.name)}<div class="sub">${esc(r.protocol)}</div></td><td>${esc(r.category_current_hint)}</td><td class="n">${money(r.eth_family_reported_usd)}</td><td>${Object.entries(r.tokens_usd||{}).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([t,v])=>`${esc(t)} ${money(v)}`).join('<br>')}${Object.keys(r.tokens_usd||{}).length>5?`<div class="sub">${Object.keys(r.tokens_usd).length-5} more symbols</div>`:''}${r.eth_family_reported_usd===0?'<div class="sub">0 in ETH-symbol subtotal; does not prove zero backing outside the breakdown</div>':''}${r.misrepresented_tokens?'<div class="sub">Adapter reports substitute token balances, not physical reserves</div>':''}</td><td>${date(r.source_timestamp)}<div class="sub">Age relative to T: ${num(r.source_age_seconds/3600,1)}h</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matches. Adjust the filter.</td></tr>';$('#protocol-more').hidden=rows.length<=15;$('#protocol-more').textContent=allProtocols?'Show 15':'Show all '+rows.length;}
let poolPage=0,filteredPools=[];
function pools(reset=true){if(reset)poolPage=0;const q=$('#pool-q').value.toLowerCase().trim(),chain=$('#pool-chain').value,cat=$('#pool-category').value,material=$('#pool-material').checked;filteredPools=R.pools.filter(r=>(!chain||r.chain===chain)&&(!cat||r.category_hint===cat)&&(!material||r.tvlUsd>=5e6)&&[r.project,r.symbol,r.pool,r.poolMeta,...(r.underlyingTokens||[])].join(' ').toLowerCase().includes(q));const key={tvl:'tvlUsd',apy:'apy',base:'apyBase'}[$('#pool-sort').value];filteredPools.sort((a,b)=>(b[key]??-Infinity)-(a[key]??-Infinity));const pages=Math.max(1,Math.ceil(filteredPools.length/40));poolPage=Math.min(poolPage,pages-1);const rows=filteredPools.slice(poolPage*40,(poolPage+1)*40);$('#pool-count').textContent=`${num(filteredPools.length)} of ${num(R.pools.length)} pools · current discovery · full mixed-pool TVL`;$('#pool-table tbody').innerHTML=rows.map(r=>`<tr><td><b>${esc(r.project)}</b><div class="sub">${esc(r.chain)} · ${esc(r.category_hint||'Unknown')}</div></td><td class="symbol">${esc(r.symbol)}${r.poolMeta?`<div class="sub">${esc(r.poolMeta)}</div>`:''}</td><td class="n">${money(r.tvlUsd)}</td><td class="n">${r.apy==null?'n/a':num(r.apy,3)+'%'}</td><td class="n">${r.apyBase==null?'n/a':num(r.apyBase,3)+'%'}</td><td class="n">${r.apyReward==null?'n/a':num(r.apyReward,3)+'%'}</td><td class="n">${r.apyMean30d==null?'n/a':num(r.apyMean30d,3)+'%'}</td><td>${a('https://defillama.com/yields/pool/'+r.pool,'Pool')}<div class="sub">Identity / mechanism require separate verification</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No matches. Try a different chain or disable the $5M threshold.</td></tr>';$('#pool-page').textContent=`Page ${poolPage+1} / ${pages}`;$('#pool-prev').disabled=poolPage===0;$('#pool-next').disabled=poolPage>=pages-1;updateExport('pools');}
function populateSelect(selector,values){const select=$(selector);[...new Set(values.filter(Boolean))].sort().forEach(v=>{const opt=document.createElement('option');opt.value=v;opt.textContent=v;select.appendChild(opt)});}

const MECHANICS=[
 {id:'E1',name:'Staking',title:'ETH pays for Ethereum’s security',text:'Validators receive consensus issuance and execution rewards: priority fees and MEV after operating expenses and operator fees. An LST makes the claim on staked ETH and its income transferable.',formula:'r ≈ issuance + tips + MEV − operator fees − penalties',units:'Rebasing stETH grows the unit balance. wstETH / rETH grow ETH per share. Comparison requires a common ETH denomination.',steps:[['ETH','Validator / staking pool'],['Consensus','Issuance and validator duties'],['Execution','Tips + MEV; operating expenses'],['LST holder','Staking income after fees']],payer:'New issuance and Ethereum users / MEV order flow.',risk:'Slashing, operator keys, withdrawal queues, concentration and market LST discounts.',count:'Backing ETH is separate from receipts held in lending, restaking, PT and vaults.',link:'dossiers/staking-restaking.html'},
 {id:'E2',name:'Restaking',title:'Reused collateral pays for an additional service',text:'ETH or an LST secures an AVS or additional service. Its staking backing already exists. Additional yield requires an identifiable payer and separate reward accounting.',formula:'r ≈ staking income + realized AVS rewards − fees − slashing losses',units:'Points and expected airdrops are not guaranteed cash income. Shared backing must not be added to LST issuer TVL.',steps:[['ETH / LST','Existing stake'],['Restaking vault','Additional conditions / slashable cover'],['AVS / service','Payer for additional security'],['Investor','Realized rewards after costs']],payer:'AVS users / operators and a disclosed subsidy budget.',risk:'Shared slashing dependencies, curator allocation, contract and bridge risks.',count:'Unique backing, AVS exposures and receipts are separate dimensions.',link:'dossiers/staking-restaking.html'},
 {id:'E3',name:'ETH loop',title:'More staked ETH per ETH of equity',text:'Deposit an LST, borrow ETH, purchase or mint another LST and repeat. ETH assets and debt are linked: profit comes from the spread between staking income and ETH borrowing costs.',formula:'r_equity ≈ L × (staking + supply) − (L − 1) × borrow − fees',units:'L = collateral / equity. With ETH debt, the key ratio is LST/ETH; oracle conversion can differ from the executable DEX price.',steps:[['ETH → LST','Initial investor equity'],['LST collateral','Aave / Spark / another lender'],['ETH debt → LST','Repeated staking deployment'],['Unwind','Source ETH → repay → release collateral']],payer:'Staking income pays ETH lenders’ interest; a positive spread remains with equity.',risk:'Rate squeeze, oracle markdowns, LST depegs, borrow cash/caps and unwind sequencing.',count:'Gross collateral minus debt equals equity. LST issuer TVL overlaps with loop collateral.',link:'library/ECONOMICS.html'},
 {id:'E4',name:'USD carry',title:'ETH collateral finances a dollar deployment',text:'ETH / LST remains collateral. The vault borrows stablecoins and deploys them into lending, credit or other dollar products. The net spread is converted into ETH NAV.',formula:'r_equity ≈ y_ETH + LTV × (y_USD − b_USD) − fees − losses',units:'Dollar-leg profit depends on destination risk and the conversion rate. The combined product remains ETH-long without a separate hedge.',steps:[['ETH / LST','Collateral and staking income'],['USD loan','RLUSD / PYUSD / USDC'],['USD destination','Lender vault / credit / cash'],['Repay + return','Dollar principal returns to the lender; net gain enters NAV']],payer:'Borrowers / credit cash flow / destination subsidies after dollar debt costs.',risk:'ETH/USD collateral drawdowns, stablecoin risk, credit recovery and redemption delays.',count:'The destination asset offsets the loan liability; borrowed principal adds no equity.',link:'dossiers/carry-credit.html'},
 {id:'E5',name:'Lending',title:'ETH lenders receive ETH borrowers’ interest',text:'Supply income depends on utilized debt. An LST collateral deposit can earn zero lending APR while retaining the receipt’s own staking income.',formula:'supply APR ≈ borrow APR × utilization × (1 − reserve factor)',units:'With almost no borrowing, even large supplied TVL generates little interest. Claims, servicing debt, cash and deficits require separate views.',steps:[['ETH lender','Supply into the market'],['Debt borrower','Loops, leverage or another use'],['Interest','Rate × outstanding debt'],['Withdraw','Requires cash and reserve eligibility']],payer:'Borrower interest; rewards have their own sponsor and are accounted for separately.',risk:'Liquidation/recovery, reserve deficits, rate curves and insufficient cash.',count:'Lender claims differ from cash and unique ETH backing. Borrowed ETH can reappear in another deployment.',link:'library/LENDING-MARKETS.html'},
 {id:'E6',name:'PT / fixed',title:'Buy a maturity claim below its redemption value',text:'SY separates principal from future yield. PT receives principal in its specified accounting unit at maturity; YT receives future yield/points until expiry.',formula:'APY ≈ (redemption unit / purchase price)^(365 / days) − 1',units:'PT-wstETH can redeem one stETH unit, rather than one wstETH. PT-weETH uses eETH accounting. An expired PT can retain principal claims.',steps:[['Yield asset','ETH / LST → SY'],['PT + YT','Separate principal and future yield'],['PT investor','Buy a discounted maturity claim'],['Maturity','Redeem through SY / underlying']],payer:'The yield/points opportunity transferred to YT holders and the market price discount.',risk:'SY/issuer backing, unit mismatch, liquidity and redemption routes.',count:'PT + YT / AMM liquidity cannot be added to SY backing as new underlying.',link:'dossiers/pendle-pt.html'},
 {id:'E7',name:'LP',title:'Income for accommodating trading flow',text:'LPs earn swap fees and sometimes incentives while their inventory changes. ETH/LST correlation does not remove depeg or adverse-selection risk.',formula:'r ≈ fees + realized incentives − inventory loss − costs − debt',units:'Concentrated liquidity earns fees only within the active range. NFT principal and uncollected fee growth are separate; imaginary reserves are not external capital.',steps:[['ETH + token','Two-sided or smart collateral'],['LP / NFT','Range / real reserves'],['Traders','Swap fees for liquidity'],['Exit','Current inventory, debt and market depth']],payer:'Traders and incentive sponsors; net return depends on the inventory path.',risk:'Range exit, depegs, IL/adverse selection, smart debt and reward dilution.',count:'ETH-side principal is separate from the other asset and aggregator stakes.',link:'dossiers/lending-lp.html'},
 {id:'E8',name:'Options',title:'Premium pays for a transferred payoff',text:'A covered call receives premium while giving up upside above the strike. Put-selling and structured payoffs have different loss scenarios. Premium is not independent staking income.',formula:'P&L = premium + underlying P&L − option obligation − fees',units:'Specify strike, maturity, collateral, exercise/settlement and ETH-denominated return. The public screen has not established aggregate ETH-options capital.',steps:[['ETH collateral','Underlying investor'],['Short option','Transferred obligation'],['Option buyer','Pays premium for the payoff'],['Settlement','Outcome depends on spot / strike']],payer:'The counterparty buying upside or downside protection.',risk:'Foregone upside, assignment, settlement, venue/counterparty and collateral risk.',count:'Collateral, option notional and external investor equity are separate.',link:'library/STRATEGY-UNIVERSE-EXPANSION.html'},
 {id:'E9',name:'Basis',title:'Long spot ETH + short derivative',text:'The spot position and short hedge aim to preserve dollar value. Perpetual funding floats; dated futures capture basis subject to hedge execution and maturity.',formula:'r_USD ≈ staking_if_staked + funding_or_basis − hedge/custody/capital costs',units:'ETH is a backing leg of a dollar product. Its dollar return cannot be compared directly with ETH-long PPS without acknowledging different exposure.',steps:[['Spot ETH','Purchased / staked backing'],['Short ETH','Matched hedge and margin'],['Funding / basis','Market cash flow'],['USD investor','Income after hedge/custody costs']],payer:'Long derivative demand / futures basis; sometimes staking and other allocations.',risk:'Negative funding, hedge mismatch, margin calls, exchange/custody and settlement risk.',count:'ETH-only matched notional is separate from total USDe backing and other assets.',link:'dossiers/ethena-basis.html'}
];
function mechanic(id){const m=MECHANICS.find(x=>x.id===id);$('#mechanic-tabs').innerHTML=MECHANICS.map(x=>`<button class="btn" role="tab" id="mt-${x.id}" aria-selected="${x.id===id}" aria-pressed="${x.id===id}" aria-controls="mechanic-body" tabindex="${x.id===id?0:-1}" data-mechanic="${x.id}">${x.id} · ${x.name}</button>`).join('');$('#mechanic-body').setAttribute('aria-labelledby','mt-'+id);$('#mechanic-body').innerHTML=`<div class="mech-top"><div><div class="mini-k">${m.id} · ${m.name}</div><h3 style="font-size:23px;margin:9px 0 14px">${m.title}</h3><p>${m.text}</p></div><div class="formula">${esc(m.formula)}<small>${m.units}</small></div></div><div class="flowline">${m.steps.map(([n,t],i)=>`<div class="flow-node"><div class="step">0${i+1}</div><b>${n}</b><small>${t}</small></div>`).join('')}</div><div class="mechanism-notes"><div><b>Who pays</b>${m.payer}</div><div><b>What can break</b>${m.risk}</div><div><b>How to count capital</b>${m.count}</div></div><div class="section-actions" style="margin-top:18px"><a class="btn" href="${m.link}">Details, evidence and limitations →</a></div>`;}

const MODELS={
 loop:{formula:'r_gross = L × y − (L − 1) × b',fields:[['L','Collateral / equity leverage',1,18,.000001,13.3245349,'×'],['y','Staking + supply APR',0,12,.000001,2.32755176,'%'],['b','ETH borrow APR',0,15,.000001,2.0738124,'%'],['fee','Management / costs on equity',0,3,.01,0,'%'],['pf','Performance fee on positive gross return',0,30,1,0,'%']]},
 carry:{formula:'r_gross = y_ETH + q × (y_USD − b_USD)',fields:[['q','USD debt / ETH collateral (LTV)',0,85,1,50,'%'],['eth','Staking income collateral',0,8,.01,2.3,'%'],['dest','USD destination APR',0,20,.01,5,'%'],['borrow','USD loan APR',0,20,.01,4,'%'],['fee','Management / costs on equity',0,3,.01,.35,'%'],['pf','Performance fee on positive gross return',0,30,1,10,'%']]},
 basis:{formula:'r_gross = staking + funding_or_basis − hedge_costs',fields:[['staking','Staking: only if backing is staked',0,8,.01,0,'%'],['funding','Funding / dated basis APR',-15,25,.1,6,'%'],['hedge','Hedge / custody / capital costs',0,8,.05,1,'%'],['fee','Management / costs',0,3,.01,.35,'%'],['pf','Performance fee on positive gross return',0,30,1,10,'%']]}
};
let model='loop';
function calcInputs(key){model=key;$$('#calc-nav button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.model===key)));$('#calc-inputs').innerHTML=MODELS[key].fields.map(([id,label,min,max,step,v,unit])=>`<label class="calc-field" for="calc-${id}"><span class="lr"><span>${label}</span><output id="out-${id}">${num(v,unit==='×'?2:2)}${unit}</output></span><input id="calc-${id}" type="range" min="${min}" max="${max}" step="${step}" value="${v}" data-unit="${unit}"></label>`).join('')+(key==='loop'?'<div class="presets"><button class="btn" id="preset-aave">Main Aave parameters</button><button class="btn" id="preset-spark">Main Spark parameters</button></div>':'');$('#calc-formula').textContent=MODELS[key].formula;$$('#calc-inputs input').forEach(x=>x.oninput=calculate);if(key==='loop'){$('#preset-aave').onclick=()=>preset(0);$('#preset-spark').onclick=()=>preset(1)}calculate();}
function preset(i){const e=R.economics[i];$('#calc-L').value=e.collateral_leverage;$('#calc-y').value=e.staking_plus_supply_APR_proxy*100;$('#calc-b').value=e.current_variable_borrow_APR*100;$('#calc-fee').value=0;$('#calc-pf').value=0;calculate();}
function calculate(){const v={};MODELS[model].fields.forEach(([id,,,,,,unit])=>{const x=$('#calc-'+id);v[id]=+x.value;$('#out-'+id).textContent=num(v[id],2)+x.dataset.unit});const requiredGross=v.fee/(1-v.pf/100);let gross,threshold,sensitivity,label;
 if(model==='loop'){gross=v.L*v.y-(v.L-1)*v.b;threshold=v.L>1?(v.L*v.y-requiredGross)/(v.L-1):null;sensitivity=-(v.L-1);label='Borrow APR at zero net return after fees';$('#calc-interpretation').textContent=`A +100 bp ETH borrow-rate increase reduces annual gross return on equity by ${num(v.L-1,2)} pp with other inputs fixed. ETH/USD direction is separate from LST/ETH ratio stress.`}
 else if(model==='carry'){gross=v.eth+v.q/100*(v.dest-v.borrow);threshold=v.q? v.borrow+(requiredGross-v.eth)/(v.q/100):null;sensitivity=-v.q/100;label='Dollar destination APR at zero net return after fees';$('#calc-interpretation').textContent=`A +100 bp dollar borrow-rate increase reduces annual return on ETH collateral equity by ${num(v.q/100,2)} pp. Dollar-leg income adds to ETH exposure; credit losses can exceed the spread.`}
 else {gross=v.staking+v.funding-v.hedge;threshold=v.hedge+requiredGross-v.staking;sensitivity=1;label='Funding / basis at zero net return after fees';$('#calc-interpretation').textContent='The result is denominated in dollars for matched spot/short exposure. Negative funding and margin/custody limits can cause losses even with stable underlying backing.'}
 const perf=Math.max(0,gross)*v.pf/100,net=gross-perf-v.fee;$('#calc-output').innerHTML=`<div class="o big"><div class="l">Modelled net APR ${model==='basis'?'in USD':'on ETH equity'}</div><div class="v" style="${net<0?'color:var(--critical)':''}">${num(net,2)}%</div></div><div class="o"><div class="l">Gross before fees/costs</div><div class="v">${num(gross,2)}%</div></div><div class="o"><div class="l">Fees + costs</div><div class="v">${num(perf+v.fee,2)} pp</div></div><div class="o big" style="background:var(--surface-2)"><div class="l">${label}</div><div class="v" style="font-size:25px;color:var(--ink)">${threshold==null?'No debt':num(threshold,2)+'%'}</div></div>`;
 let example;
 if(model==='loop')example=`With 100 ETH of equity, the model holds ${num(100*v.L,2)} ETH of collateral and ${num(100*(v.L-1),2)} ETH of debt. Annual asset income is ${num(v.L*v.y,3)} ETH; debt interest costs ${num((v.L-1)*v.b,3)} ETH. After ${num(perf+v.fee,3)} ETH of model fees and costs, the result is ${num(net,3)} ETH.`;
 else if(model==='carry')example=`With 100 ETH of collateral, dollar debt is worth ${num(v.q,2)} ETH at an unchanged ETH price. Staking earns ${num(v.eth,3)} ETH; dollar reinvestment earns ${num(v.q*v.dest/100,3)} ETH equivalent and interest costs ${num(v.q*v.borrow/100,3)} ETH equivalent. Model fees and costs are ${num(perf+v.fee,3)} ETH; the net result is ${num(net,3)} ETH.`;
 else example=`For $100 of matched spot and short exposure, annual staking income is $${num(v.staking,3)} and funding or basis is $${num(v.funding,3)}. Hedge costs are $${num(v.hedge,3)}; other fees and costs are $${num(perf+v.fee,3)}. The net model result is $${num(net,3)}.`;
 $('#calc-worked-example').textContent=example;
}

const accountLabel=id=>({main_aave:'Main vault / Aave',main_spark:'Main vault / Spark',drone_aave:'Drone / Aave',drone_spark:'Drone / Spark'}[id]||id);
const productList=[['etherfi','ether.fi Liquid ETH','177 171 ETH book','var(--s1)'],['fluid','Fluid Lite ETH','77 364 stETH book','var(--s2)'],['treehouse','Treehouse tETH','19 860 IAU book','var(--s4)'],['concrete','Concrete ETH','Private / shared custody','var(--s7)'],['cian','CIAN rsETH','1 417 rsETH book','var(--s5)']];
