const flows=arr=>'<div class="flowline">'+arr.map(([label,text,url],i)=>`<div class="flow-node"><div class="step">0${i+1}</div><b>${label}</b><small>${text}</small>${url?`<a href="${url}" target="_blank" rel="noopener">Contract ↗</a>`:''}</div>`).join('')+'</div>';
function productTitle(title,lede,id){return `<div class="product-title"><div><h3 style="font-size:27px">${title}</h3><p>${lede}</p></div>${article(id)}</div>`;}
function renderEtherfi(){const e=R.etherfi,b=R.balance;return productTitle('ether.fi Liquid ETH','A managed ETH portfolio combining staking loops, dollar carry and liquidity provision. Shares circulate on Ethereum and Optimism; strategy exposure also includes Monad.','etherfi-liquid-eth')+facts([['Published book NAV',num(e.published_book_nav_eth,0)+' ETH',money(e.published_book_nav_usd_nearest_quote)],['PPS at T',num(e.rate_eth_per_share,6)+' ETH','Last mark: 2 Oct, 06:26 UTC'],['Management fee','35 bp','Accountant parameter at T'],['Partial NAV residual',num(b.unresolved_residual_pct,3)+'%',money(b.unresolved_residual_usd)+' unresolved']])+`<div class="panel"><h3>How the money moves</h3>${flows([['ETH → share','Shares: Ethereum 125,539; Optimism 34,533. One logical burn/mint product.',explorer('ethereum','0xf0bb20865277abd641a307ece5ee04e79073416c')],['ETH loops','weETH collateral; WETH debt. Aave and Spark amplify the staking spread.'],['USD carry + LP','Drone, Morpho, LoanManager and PRIME; LP NFTs and a nested Monad claim.'],['PPS → exit','Accountant book value → share sale or queue → underlying portfolio unwind.']])}<div class="cols"><div><h3>Who pays</h3><ul class="small"><li>Ethereum issuance and transaction fees reward validators.</li><li>Crypto borrowers through the RLUSD lending portfolio.</li><li>PRIME credit through the PYUSD market.</li><li>Swap fees from active weETH/WETH ranges.</li><li>Rewards only when entitlement and realization are evidenced separately.</li></ul></div><div><h3>What the manager controls</h3><p class="small">The captured interface identifies Veda as infrastructure and Nonce as strategy provider. Contract roles were reconstructed at T. The owner has a 24-hour minimum delay, while a separate role can change the management fee. See the permission table below.</p><p class="small">A zero owner on an individual contract does not remove Authority/roles. Published PPS does not independently verify backing.</p></div></div></div><div class="panel"><h3>Current UI: strategy composition</h3><div class="sub">3 October, after T. Display weights are not used to reconstruct fixed-block positions.</div><div class="tblwrap"><table><thead><tr><th>Sleeve</th><th class="n">Weight</th><th class="n">Display APY</th><th>Mechanism</th></tr></thead><tbody>${[['Stablecoin carry','52.27%','2.37%','E4'],['weETH looping','19.57%','6.02%','E3'],['Sentora PRIME carry','12.39%','3.54%','E4 / credit'],['Liquid Monad ETH','6.28%','1.92%','Nested book claim'],['Uniswap LP','4.05%','0.81%','E7'],['Spark looping','2.08%','5.06%','E3'],['Fluid LP','1.81%','4.81%','E7 / smart debt'],['Withdrawals','1.55%','0.00%','Liquidity']].map(r=>'<tr>'+r.map((v,i)=>`<td class="${i===1||i===2?'n':''}">${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div><p class="note" style="margin-top:12px">Carry 64.66%; explicit loops 21.65%. Weighted displayed APY 3.201% and UI 14-day APY 3.23% use different calculations. Ethereum 93.72% / Monad 6.28% deployment differs from Ethereum / Optimism share circulation.</p></div><div class="panel"><h3>Collateral, debt and equity at T</h3><div class="tblwrap"><table><thead><tr><th>Account</th><th class="n">Collateral</th><th class="n">Debt</th><th class="n">Equity</th><th class="n">L</th><th class="n">HF</th></tr></thead><tbody>${e.aave_spark_accounts.map(r=>`<tr><td>${esc(accountLabel(r.position))}</td><td class="n">${money(r.collateral_oracle_usd)}</td><td class="n">${money(r.debt_oracle_usd)}</td><td class="n">${money(r.equity_oracle_usd)}</td><td class="n">${num(r.gross_leverage,3)}×</td><td class="n">${num(r.health_factor,5)}</td></tr>`).join('')}</tbody></table></div><div class="metric-strip"><div>Aave debt / reserve cash<b>152.1%</b></div><div>Aave oracle markdown to HF = 1<b>2.637%</b></div><div>Borrow uplift to zero model return<b>44.3 bp</b></div></div><p class="note">Loop HF depends on the LST/ETH conversion oracle. Drone stable-debt accounts face ETH/USD collateral stress. The rate threshold combines a trailing-30-day staking proxy with instantaneous supply/borrow APR, before fees and rewards.</p></div><div class="panel"><h3>Book NAV and reconstructed claims</h3><div class="metric-strip"><div>Published book<b>${money(b.published_book_nav_usd)}</b></div><div>Partial reconstruction<b>${money(b.partial_reconstruction_usd)}</b></div><div>Unresolved residual<b>${money(b.unresolved_residual_usd)}</b></div></div><p class="small">Valued positions/claims explain approximately 97.37% of the book. This does not verify their independent physical backing. Nested Liquid Monad uses its own Ethereum Accountant: 8,128.762 ETH, $21.687M. Remote underlying remains unresolved.</p><p class="small">Uniswap NFT principal: 6,875.525 ETH, $18.344M, excluding uncollected fee growth. Fluid NFT 4241 / vault 74: net equity approximately 3,073.874 ETH, $8.201M, using real reserves and subtracting wstETH debt.</p><details class="more"><summary>62-row partial balance sheet and valuation methods</summary><div class="body"><div class="tblwrap"><table><thead><tr><th>Position / claim</th><th class="n">USD</th><th>Valuation</th></tr></thead><tbody>${b.lines.map(r=>`<tr><td>${esc(r.label)}</td><td class="n ${r.usd<0?'num-down':''}">${money(r.usd)}</td><td>${esc(r.valuation_method||r.kind||'')}</td></tr>`).join('')}</tbody></table></div><p class="small">${b.material_gaps.map(esc).join('<br>')}</p></div></details><a href="data/etherfi_partial_balance_sheet.json" download>Full balance JSON →</a></div>${renderEtherfiControl()}<div class="panel"><h3>What changed over time</h3><div class="timeline"><div class="event"><time>2024 → T</time><p>Liquid ETH gained 6.850% over 730 days at published PPS, versus stETH’s 5.488%. Liquid ETH gained 3.870% over the last year.</p></div><div class="event"><time>06.2026</time><p>Management fees changed 25 → 50 → 65 bp. Today’s fee must not be applied retrospectively to the entire historical P&L.</p></div><div class="event"><time>07-08.2026</time><p>Fees changed 65 → 80 → 70 → 10 → 35 bp. Captured 719 Accountant events: 653 rate updates and 66 parameter updates.</p></div><div class="event"><time>02.10.2026</time><p>Both share networks, main/Drone Aave/Spark, Morpho, LoanManager, PositionManager, NFTs and the separate Monad Accountant were checked.</p></div></div></div><div class="verdict-box"><b>Finding.</b> Measured excess over staking exists, but totals 1.36 pp over two years. Complexity adds rate, credit, oracle, custody and exit dependencies. Remote backing, accrued interest, rewards, fees, bridge messages and execution remain necessary for final reconciliation.</div>`;}

function renderEtherfiControl(){const components=[['Accountant','0x0d05d94a5f1e76c18fbeb7a13d17c8a314088198','Published rate / fee state. Ethereum and Optimism layouts differ; complete fee settlement remains unreconstructed.'],['Teller','0x9aa79c84b79816ab920bbce20f8f74557b514734','Deposit / withdrawal eligibility and burn/mint cross-chain shares. Pending messages remain open.'],['Authority','0x485bde66bb668a51f2372e34e45b1c6226798122','Permissions layer; owner is TimelockController. A zero owner on another vault contract does not remove roles.'],['Timelock','0xd829f278016b90fec735f9a12bf8b75e06102c89','Owner minimum delay: 24 hours. A separate fee-setting role is verified; complete proposer/executor membership remains open.'],['Queue','0x0d2df071207e18ca8638b4f04e98c53155ec2ce0','weETH requests: 1h maturity, 3d minimum deadline, 0-10 bp discount. These parameters do not guarantee payout time.'],['Drone','0x0a42b2f3a0d54157dbd7cc346335a4f1909fc02c','Exclusive controller: main vault. Separate Aave / Spark stable-debt accounts.'],['LoanManager','0xc936e848688c9f035fa0e7a0e4dbcf26a01245f3','Owned by the main vault; 19,063.547 weETH collateral and approximately $34.289M stored RLUSD debt.'],['PositionManager','0x528353aea55dbbbf18be26d5726afe6585898dc5','Owned by the main vault; 32.272M PRIME units, approximately $34.285M oracle book value.']];return `<div class="panel"><h3>Contract architecture and exit routes</h3><div class="tblwrap"><table><thead><tr><th>Component</th><th>Identity</th><th>Verified function / limitation</th></tr></thead><tbody>${components.map(([role,addr,what])=>`<tr><td><b>${role}</b></td><td>${a(explorer('ethereum',addr),short(addr))}</td><td>${what}</td></tr>`).join('')}</tbody></table></div><div class="diagram-grid" style="margin-top:20px"><div class="diagram-col"><h3>Route 1 · share sale</h3><div>LiquidETH → secondary market<small>Depends on depth and discount</small></div><div class="arrow">↓</div><div>Payout token<small>Market price can differ from PPS</small></div></div><div class="diagram-col"><h3>Route 2 · queue</h3><div>weETH withdrawal request<small>WETH queue is disabled at T</small></div><div class="arrow">↓</div><div>Solver / maturity / deadline<small>Time parameters do not guarantee execution</small></div><div class="arrow">↓</div><div>Received weETH<small>Still requires ETH conversion / redemption</small></div></div><div class="diagram-col"><h3>Route 3 · portfolio unwind</h3><div>Available ETH / dollar debt asset<small>Cash / market depth / destination withdrawal</small></div><div class="arrow">↓</div><div>Repay debt → release collateral<small>Operation ordering and caps</small></div><div class="arrow">↓</div><div>LST redemption / bridge settlement<small>Queue and in-flight claims accounted for separately</small></div></div></div><p class="note" style="margin-top:16px">At T, Teller permits WETH deposits but not direct withdrawals; weETH is enabled in both directions. Time to ETH after exiting a share depends on several independent routes.</p><div class="section-actions"><a href="#evidence-C03">NAV / share proof C03</a><a href="#evidence-C04">Balance proof C04</a><a href="#evidence-C05">Loop proof C05</a><a href="#evidence-C20">Cash / debt proof C20</a></div></div>`;}

function renderFluid(){return productTitle('Fluid Lite ETH V2','LST looping portfolio denominated in rebasing stETH. Gross assets and debt substantially exceed net equity.','fluid-lite')+facts([['Book assets','77 364 stETH','63 316 shares'],['Gross / net leverage','7.759×','Debt ratio 87.11%'],['730d ETH return','8.824%','Annualized 4.319%'],['Withdraw fee','5 bp','getWithdrawFee(1 stETH) at T']])+`<div class="panel"><h3>From stETH to a leveraged portfolio</h3>${flows([['stETH → shares','Vault totalAssets / totalSupply gives 1.221875 stETH per share.',explorer('ethereum','0xa0d3707c569ff8c87fa923d3823ec5d81c98be78')],['Strategy routing','ETH-equivalent assets and borrowing aggregate at portfolio level.'],['Spread','Debt amplifies staking exposure; leverage does not generate free yield.'],['Withdraw','Repay, release assets and return stETH; the withdrawal fee is checked separately.']])}<div class="cols"><div><h3>Balance sheet at T</h3><p class="small">getNetAssets: approximately 600,256 ETH-equivalent gross assets, 522,809 debt and 77,359 net after revenue. Contract valuation assumes stETH/eETH/WETH parity.</p><p class="small">Book assets of 77,364.031 stETH exceed the net view by 4.692 stETH. This remains an accounting gap without automatically being classified as loss.</p></div><div><h3>Who pays and who controls</h3><p class="small">Staking and market income pay the borrowing cost. View-module identity 0x9fb2… is verified through router/source; the Dummy ABI is an interface.</p><p class="small">Aggregate maximum debt ratio: approximately 92%. Team allocation getter at T is zero; this is not a complete governance-role review.</p></div></div></div><div class="verdict-box"><b>Finding.</b> Highest book return in the selected two-year window, while Liquid ETH leads over the last year. Ranking changes with the window. Investor comparison requires market valuation, debt/liquidity look-through and full withdrawal simulation.</div>`;}
function renderTreehouse(){return productTitle('Treehouse tETH','Additional managed yield on wstETH. Internal asset: IAU_wstETH; the ETH denominator is reconstructed historically.','treehouse-teth')+facts([['Book assets','19 860 IAU','19 712 tETH shares'],['tETH / IAU PPS','1.007528','Accounting unit differs from physical wstETH'],['730d ETH return','6.276%','IAU-only growth: 0.748%'],['Standard / fast','~7d / 0.5%','Fast route has a capacity limit']])+`<div class="panel"><h3>Two yield layers and two accounting units</h3>${flows([['ETH → wstETH','Underlying staking conversion grows over time.'],['wstETH → IAU','wstETH underlying identity verified with 33 historical calls.',explorer('ethereum','0x1b6238e95bbcabee58997c99badd4154ad68ba92')],['IAU → tETH','TotalAssets / supply gives accounting PPS.',explorer('ethereum','0xd11c452fc99cf405034ee446803b6f6c1f6d5ed8')],['Redemption','wstETH through liquidity or standard unwind.']])}<div class="formula">tETH/ETH = (tETH/IAU accounting value) × (IAU underlying wstETH/ETH)<small>IAU growth and total ETH return measure different things. Historically verified denomination does not establish independent portfolio backing.</small></div><div class="cols"><div><h3>Who pays</h3><p class="small">Underlying staking plus managed MEY. Official terms charge 20% of positive MEY as a performance fee. Separate underlying staking from strategy income.</p><p class="small">Over 730 days, IAU PPS gained 0.7475%; including wstETH conversion, ETH book return was 6.2761%. The 365-day ETH return was 2.7845%.</p></div><div><h3>Withdrawal path</h3><p class="small">Standard direct redemption takes approximately seven days, with a 5 bp fee and a minimum-rate formula between request and claim. Smaller requests route through Curve liquidity; governance sets the routing band.</p><p class="small">Fast redemption costs 0.5% when capacity is available. Independent NAV/custody reconciliation remains incomplete; unknown KPKWSTETH was not automatically included in ETH totals.</p>${a('https://docs.treehouse.finance/protocol/tasset/architecture/redemption-process','Primary redemption terms')}</div></div></div><div class="verdict-box"><b>Finding.</b> ETH conversion materially changes measured return. A separate fast-exit fee is material relative to excess and belongs in the comparison horizon.</div>`;}
function renderConcrete(){return productTitle('Concrete Delta weETH / wstETH Plus','Large published claims with private terms and shared custody. Share ownership changes the interpretation of inflows.','concrete-eth')+facts([['Delta book assets','278 171 weETH','PPS: 1 weETH / share at T'],['wstETH Plus','36 440 wstETH','PPS: 1 wstETH / share at T'],['Custody Safe','3 of 5','One Safe is linked to both vaults'],['External equity','Unresolved','Private payouts are undisclosed']])+`<div class="panel"><h3>Share contracts and the shared portfolio</h3>${flows([['ctDeltaWeETH','Genesis supply created through UnbackedMint on 16 Dec 2025.',explorer('ethereum','0xb9dc54c8261745cb97070cefbe3d3d815aee8f20')],['Ownership','One address holds all Delta supply at T; the custody Safe holds all ctwstETH supply.'],['3-of-5 Safe','Shared Aave / Morpho positions; complete allocation between vaults remains unresolved.',explorer('ethereum','0x7ee29373f075ee1d83b1b93b4fe94ae242df5178')],['Private payouts','Public PPS does not reveal investor terms / external distributions.']])}<div class="cols"><div><h3>What was verified</h3><p class="small">Getters and strategy links connect both vaults to the shared multisig. Delta’s initial mint has no asset transfer in the genesis path. One holder owns all 278,170.834 shares at T. The Safe holds all ctwstETH supply.</p><p class="small">Safe Aave collateral: approximately $503.453M; debt $105.736M; equity $397.716M; HF 3.822. Current Morpho wstETH/USDT debt of $70.395M is a separate observation after T.</p></div><div><h3>Economic interpretation</h3><p class="small">This can reflect migration of an existing portfolio and internal claims. It does not prove fraud, absent backing or new external deposits.</p><p class="small">The approximately $953M daily adapter NAV cannot be added to the entire custody NAV. Accounting update times and validity windows require mark-freshness checks. Flat PPS need not mean zero investor yield with private distributions.</p></div></div></div><div class="verdict-box"><b>Finding.</b> Portfolio origin, holder rights and allocated liabilities of each vault remain necessary. Published claims are not equated with external capital.</div>`;}
function renderCian(){return productTitle('CIAN rsETH vault','rsETH PPS converted into ETH using a historically verified oracle. Rewards, market depegs and incident attribution remain separate.','cian-rseth')+facts([['Book assets','1 416.559 rsETH','1 477.394 shares'],['Asset PPS','0.958823 rsETH','Per share'],['730d ETH return','1.085%','rsETH-unit return −4.118%'],['Published terms','8% / 0.02%','Profit fee / exit policy; override not checked']])+`<div class="panel"><h3>The correct comparison unit</h3>${flows([['rsETH','Restaking receipt with its own ETH conversion.'],['CIAN share','rsETH per share can decline.',explorer('ethereum','0xd87a19ff681ae98bf10d2220d1ae3fbd374ade4e')],['Historical oracle','rsETH/ETH at window starts and T is verified separately.'],['Investor result','ETH book return; external rewards and execution enter only with evidence.']])}<div class="formula">ETH per share = rsETH per share × rsETH/ETH historical rate<small>Over 730 days, rsETH per share declined 4.118%; rsETH conversion offset part of this decline. ETH book return: +1.085%, or approximately 0.541% annualized.</small></div><div class="cols"><div><h3>What returns reveal</h3><p class="small">365-day ETH book return was +2.2455%, while asset PPS declined 0.2105%. Full investor P&L requires external rewards and actual exit costs.</p><p class="small">CIAN’s total protocol TVL is largely BTC/USD. Dated ETH-family exposure is approximately $6.718M; the entire $308M protocol is not assigned to ETH yield.</p></div><div><h3>rsETH dependency</h3><p class="small">Bridge incidents, lending recovery and sunset-network procedures introduce separate claim/exit risks. Oracle conversion does not establish executable market value.</p><p class="small">Each historical PPS loss requires event reconciliation. Without that ledger, it has not been causally attributed to the incident.</p></div></div></div><div class="verdict-box"><b>Finding.</b> Conversion fixes denomination while custody and execution still require verification. A high displayed APY or rising issuer oracle can coexist with declining asset units per share.</div>`;}
function product(id,updateURL=true){const row=productList.find(x=>x[0]===id)||productList[0];$('#product-tabs').innerHTML=productList.map(([key,name,note,col])=>`<button role="tab" id="pt-${key}" aria-selected="${key===row[0]}" aria-controls="product-content" tabindex="${key===row[0]?0:-1}" data-product="${key}" style="--pc:${col}"><span class="nm"><i></i>${name}</span><small>${note}</small></button>`).join('');$('#product-content').setAttribute('aria-labelledby','pt-'+row[0]);$('#product-content').style.setProperty('--pc',row[3]);$('#product-content').innerHTML=({etherfi:renderEtherfi,fluid:renderFluid,treehouse:renderTreehouse,concrete:renderConcrete,cian:renderCian}[row[0]])();if(row[0]==='etherfi'){$('#product-content').insertAdjacentHTML('beforeend',productHistoryPanel());etherfiHistory()}$('#product-content').insertAdjacentHTML('beforeend',productReview(row[0]));if(updateURL){const u=new URL(location.href);u.searchParams.set('product',row[0]);history.replaceState(null,'',u)}}

const colors={'Fluid Lite ETH':'#159986','Liquid ETH':'#6861d8','Treehouse tETH':'#bc8c25','stETH':'#377cbd','weETH':'#b575a4','CIAN rsETH':'#c7675d'};
const hiddenSeries=new Set();
function lineChart(series,{yLabel='',format=v=>num(v,1),zero=false}={}){
 const W=innerWidth<560?420:720,H=300,p={l:74,r:14,t:24,b:34},points=series.flatMap(s=>s.points).filter(r=>r[1]!=null);
 if(!points.length)return '<div class="empty">No dated observations available.</div>';
 const times=[...new Set(points.map(r=>r[0]))].sort((a,b)=>a-b),values=points.map(r=>r[1]),xmin=times[0],xmax=times.at(-1);
 let ymin=zero?0:Math.min(...values),ymax=Math.max(...values),pad=Math.max((ymax-ymin)*.12,ymax===ymin?Math.max(Math.abs(ymax)*.05,.01):.12);
 if(!zero)ymin-=pad;ymax+=pad;p.l=Math.max(65,...Array.from({length:5},(_,i)=>String(format(ymin+(ymax-ymin)*i/4)).length*7+16));
 const x=t=>p.l+(t-xmin)/Math.max(1,xmax-xmin)*(W-p.l-p.r),y=v=>p.t+(ymax-v)/(ymax-ymin)*(H-p.t-p.b);
 let svg=`<svg class="line-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(yLabel)}"><title>${esc(yLabel)}</title>`;
 for(let i=0;i<=4;i++){const v=ymin+(ymax-ymin)*i/4;svg+=`<line x1="${p.l}" y1="${y(v)}" x2="${W-p.r}" y2="${y(v)}" stroke="var(--grid)"/><text x="${p.l-10}" y="${y(v)+4}" text-anchor="end" fill="var(--muted)" font-size="11" font-family="var(--mono)">${esc(format(v))}</text>`;}
 for(let i=0;i<=5;i++){const t=xmin+(xmax-xmin)*i/5;svg+=`<text x="${x(t)}" y="${H-15}" text-anchor="middle" fill="var(--muted)" font-size="11" font-family="var(--mono)">${date(t).slice(0,7)}</text>`;}
 series.forEach(s=>{let path='',newSegment=true,last=null;s.points.forEach(([t,v])=>{if(v==null){newSegment=true;return;}if(last&&t-last>45*86400)newSegment=true;path+=`${newSegment?'M':'L'}${x(t).toFixed(2)},${y(v).toFixed(2)} `;newSegment=false;last=t;});svg+=`<path d="${path}" stroke="${s.color}" fill="none" stroke-width="2.4"/>`;s.points.filter(r=>r[1]!=null).forEach(([t,v])=>svg+=`<circle cx="${x(t)}" cy="${y(v)}" r="3" fill="${s.color}"/>`);});
 times.forEach((t,i)=>{const left=i?(x(times[i-1])+x(t))/2:p.l,right=i<times.length-1?(x(t)+x(times[i+1]))/2:W-p.r,rows=series.map(s=>{const v=s.points.find(r=>r[0]===t)?.[1];return{name:s.name,color:s.color,value:v==null?'No observation':format(v)};}),note=date(t)+'\n'+rows.map(r=>r.name+': '+r.value).join('\n');svg+=`<rect class="chart-month-hit" tabindex="${i===0?0:-1}" x="${left}" y="${p.t}" width="${right-left}" height="${H-p.t-p.b}" fill="transparent" data-chart-tip="${esc(note)}" data-chart-title="${date(t)}" data-chart-rows="${esc(JSON.stringify(rows))}" aria-label="${esc(note.replaceAll('\n',' · '))}"/>`;});
 return '<div class="research-chart">'+svg+'</svg><div class="chart-float" role="status" hidden></div></div>';
}
function wealth(){const series=Object.entries(R.wealth.series).filter(([k])=>!hiddenSeries.has(k)).map(([name,rows])=>({name,color:colors[name],points:rows.map(r=>[r.timestamp,r.normalized_ETH_book_wealth])}));$('#wealth-controls').innerHTML=Object.keys(R.wealth.series).map(n=>`<button class="legend-toggle" aria-pressed="${!hiddenSeries.has(n)}" data-series="${n}" style="--col:${colors[n]}"><i></i>${n}</button>`).join('');wealthTable();$('#wealth-chart').innerHTML=series.length?lineChart(series,{yLabel:'100 ETH at published book PPS',format:v=>num(v,2)+' ETH'}):'<div class="empty">Select at least one series above.</div>';$$('#wealth-chart [data-point]').forEach(c=>{c.onmouseenter=c.onfocus=()=>$('#wealth-tooltip').textContent=c.dataset.point});}
function returns(days){$$('#return-window button').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.days===days)));const base=R.etherfiReturns.find(r=>r.days===days);let rows=[['Liquid ETH',base.liquidETH_cumulative_return,base.liquidETH_annualized_apy,'Accountant PPS'],['stETH',base.stETH_cumulative_return,base.stETH_annualized_apy,'Historical rebasing / conversion'],['weETH',base.weETH_cumulative_return,base.weETH_annualized_apy,'Historical issuer rate'],...R.returns.filter(r=>r.days===days&&['Fluid Lite ETH','Treehouse tETH','CIAN rsETH'].includes(r.product)).map(r=>[r.product,r.ETH_pps_cumulative_return,r.ETH_pps_annualized_apy,r.product==='Treehouse tETH'?'IAU PPS × wstETH/ETH':r.product==='CIAN rsETH'?'rsETH PPS × historical oracle':'stETH-denominated PPS'])];rows.sort((a,b)=>(b[1]??-Infinity)-(a[1]??-Infinity));$('#returns-table tbody').innerHTML=rows.map(([name,ret,apy,note])=>`<tr><td><i class="pdot" style="background:${colors[name]}"></i><b>${name}</b></td><td class="n">${pct(ret,4)}</td><td class="n">${pct(apy,4)}</td><td class="n">${ret==null?'n/a':num((ret-base.stETH_cumulative_return)*100,4)}</td><td>${note}${ret==null?' · unavailable, not zero':''}</td></tr>`).join('');}
function protocolHistory(){const slug=$('#history-protocol').value;const rows=R.protocolHistory.filter(r=>r.protocol===slug).sort((a,b)=>a.period.localeCompare(b.period));const name=R.protocols.find(r=>r.protocol===slug)?.name||slug;$('#protocol-history-chart').innerHTML=columnChart([{name,color:'#6861d8',points:rows.map(r=>[r.target_timestamp,r.eth_family_reported_usd])}],{label:name+' · dated ETH-family USD',format:money});$('#protocol-history-table tbody').innerHTML=rows.map(r=>`<tr><td>${r.period}</td><td class="n">${money(r.eth_family_reported_usd)}</td><td>${date(r.source_timestamp)}</td><td>${r.tokens_units?Object.entries(r.tokens_units).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([k,v])=>`${esc(k)} ${num(v,0)}`).join(' · '):r.eth_family_reported_usd==null?'No observation; not zero':'ETH-equivalent value; native units kept separately'}</td></tr>`).join('');updateExport('protocol');}
function lending(){$('#lending-table tbody').innerHTML=R.lending.map(r=>`<tr><td>${a(explorer(r.chain,r.pool),r.protocol+' / '+r.chain)}<div class="sub">block ${num(r.block)}</div></td><td class="n">${num(r.lender_claim_units,1)}</td><td class="n">${num(r.debt_units,1)}</td><td class="n">${num(r.reserve_cash_units,1)}</td><td class="n">${pct(r.supply_APR)}</td><td class="n">${pct(r.variable_borrow_APR)}</td><td class="n">${num(r.extra_getters?.['getReserveDeficit(address)'],3)}</td></tr>`).join('');$('#stress-table tbody').innerHTML=R.stress.map(r=>`<tr><td>${esc(accountLabel(r.account))}</td><td class="n">${num(r.collateral_leverage,3)}×</td><td class="n">${num(r.HF,5)}</td><td class="n">${pct(r.oracle_markdown_to_HF_1)}</td><td class="n">${num(r.borrow_plus_100bp_isolated_equity_return_change_pp,3)} pp</td></tr>`).join('');}
function evidence(){const q=$('#evidence-q').value.toLowerCase().trim();$('#evidence-list').innerHTML=R.evidence.filter(r=>/^c\d{2}$/.test(q)?r.id.toLowerCase()===q:[r.id,r.claim,r.time_scope_and_limit,r.evidence_type,...r.semantic_inputs.map(x=>x.path),...r.source_responses.flatMap(x=>[x.url,x.key])].join(' ').toLowerCase().includes(q)).map(r=>{const urls=[...new Map(r.source_responses.map(s=>[s.url,s])).values()];return `<div class="source-card" id="evidence-${r.id}"><strong>${r.id}</strong> <b>${esc(r.claim)}</b><p>${esc(r.time_scope_and_limit)} · ${esc(r.evidence_type)}</p><div class="sources">${urls.slice(0,8).map(s=>a(s.url,shortSource(s.url))).join('')}</div><details><summary>Files and provenance</summary>${r.semantic_inputs.map(s=>`<p><code>${esc(s.path)}</code><br><code>SHA256 ${esc(s.sha256)}</code></p>`).join('')}${r.source_responses.slice(0,10).map(s=>`<p><code>${esc(s.key)} · ${esc(s.retrieved_at)}</code><br><code>${esc(s.path)}</code></p>`).join('')}</details></div>`}).join('')||'<p class="empty">No matches.</p>';}
function shortSource(url){try{const u=new URL(url);return u.hostname+u.pathname.slice(0,62)}catch{return url}}
function creditTable(){const symbols=Object.fromEntries(R.carryAssets.map(r=>[r.address.toLowerCase(),r.symbol]));$('#credit-table tbody').innerHTML=R.credit.map(r=>`<tr><td>${a('https://app.morpho.org/ethereum/market/'+r.market_id,(r.performance_fee_fraction===.1?'senRLUSD':'senPRIME')+' / '+(symbols[r.collateral.toLowerCase()]||short(r.collateral)))}</td><td class="n">${num(r.expected_adapter_supply_loan_units,0)}</td><td class="n">${pct(r.share_of_vault_assets,2)}</td><td class="n">${pct(r.stored_market_utilization,2)}</td><td class="n">${num(r.lookthrough_self_credit_notional_loan_units,0)}</td></tr>`).join('');}
function openHash(instant=false){const h=location.hash;if(!h)return;if(h.startsWith('#evidence-')&&!document.getElementById(h.slice(1))){$('#evidence-q').value='';evidence()}const target=document.getElementById(decodeURIComponent(h.slice(1)));if(target){for(let p=target.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;target.scrollIntoView({behavior:instant===true?'instant':'smooth'})}}
function initKeyboardTabs(selector,key,ids,select){$(selector).addEventListener('keydown',ev=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;const b=ev.target.closest('button');if(!b)return;ev.preventDefault();let i=ids.indexOf(b.dataset[key]);i=ev.key==='Home'?0:ev.key==='End'?ids.length-1:(i+(ev.key==='ArrowRight'?1:-1)+ids.length)%ids.length;select(ids[i]);$(selector).querySelector(`[data-${key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())}="${ids[i]}"]`).focus()})}
function init(){initTheme();initChains();capital('underlying');$('#capital-tabs').onclick=e=>{const b=e.target.closest('[data-capital]');if(b)capital(b.dataset.capital)};populateSelect('#protocol-category',R.protocols.map(r=>r.category_current_hint));['#protocol-q','#protocol-category','#protocol-sort'].forEach(s=>$(s).addEventListener('input',protocols));$('#protocol-more').onclick=()=>{allProtocols=!allProtocols;protocols()};protocols();populateSelect('#pool-chain',R.pools.map(r=>r.chain));populateSelect('#pool-category',R.pools.map(r=>r.category_hint));['#pool-q','#pool-chain','#pool-category','#pool-sort','#pool-material'].forEach(s=>$(s).addEventListener('input',()=>pools()));$('#pool-prev').onclick=()=>{poolPage--;pools(false)};$('#pool-next').onclick=()=>{poolPage++;pools(false)};pools();mechanic('E4');$('#mechanic-tabs').onclick=e=>{const b=e.target.closest('[data-mechanic]');if(b)mechanic(b.dataset.mechanic)};initKeyboardTabs('#mechanic-tabs','mechanic',MECHANICS.map(m=>m.id),mechanic);calcInputs('carry');$('#calc-nav').onclick=e=>{const b=e.target.closest('[data-model]');if(b)calcInputs(b.dataset.model)};product(new URLSearchParams(location.search).get('product')||'etherfi',false);$('#product-tabs').onclick=e=>{const b=e.target.closest('[data-product]');if(b)product(b.dataset.product)};initKeyboardTabs('#product-tabs','product',productList.map(m=>m[0]),product);wealth();$('#wealth-controls').onclick=e=>{const b=e.target.closest('[data-series]');if(!b)return;hiddenSeries.has(b.dataset.series)?hiddenSeries.delete(b.dataset.series):hiddenSeries.add(b.dataset.series);wealth()};returns(730);$('#return-window').onclick=e=>{const b=e.target.closest('[data-days]');if(b)returns(+b.dataset.days)};R.protocols.slice().sort((a,b)=>b.eth_family_reported_usd-a.eth_family_reported_usd).forEach(r=>{const opt=document.createElement('option');opt.value=r.protocol;opt.textContent=r.name;$('#history-protocol').appendChild(opt)});$('#history-protocol').onchange=protocolHistory;protocolHistory();lending();creditTable();evidence();$('#evidence-q').oninput=evidence;window.addEventListener('hashchange',openHash);openHash();const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)$$('nav.sec a').forEach(a=>a.setAttribute('aria-current',String(a.hash==='#'+e.target.id)))}),{rootMargin:'-10% 0px -75% 0px'});$$('main>section').forEach(s=>observer.observe(s));document.documentElement.dataset.loaded='true';}
